function deleteGreatestValue(grid) {
  for (const row of grid) {
    row.sort((a, b) => a - b);
  }
  const columns = grid[0].length;
  let answer = 0;
  for (let col = columns - 1; col >= 0; col--) {
    let largest = 0;
    for (const row of grid) {
      largest = Math.max(largest, row[col]);
    }
    answer += largest;
  }
  return answer;
}

