function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const m = pick(40, 50), n = pick(40, 50);
    return [Array.from({ length: m }, () => Array.from({ length: n }, () => pick(1, 100)))];
  }
  const m = pick(1, 5), n = pick(1, 5);
  const top = rand() < 0.3 ? 3 : rand() < 0.5 ? 10 : 100;
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => pick(1, top)))];
}
